import{_ as r,o as a,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"প্রি-অ্যাঙ্কর যুগ","description":"","frontmatter":{},"headers":[],"relativePath":"bn/71-前锚点时代.md","filePath":"bn/71-前锚点时代.md","lastUpdated":null}'),d={name:"bn/71-前锚点时代.md"};function i(e,t,n,s,h,u){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="প্রি-অ্যাঙ্কর-যুগ" tabindex="-1">প্রি-অ্যাঙ্কর যুগ <a class="header-anchor" href="#প্রি-অ্যাঙ্কর-যুগ" aria-label="Permalink to &quot;প্রি-অ্যাঙ্কর যুগ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>71</td></tr><tr><td>মডিউল</td><td>ঐতিহাসিক যুগ ও গুরুত্বপূর্ণ ঘটনা</td></tr><tr><td>মূল কীওয়ার্ড</td><td>প্রি-অ্যাঙ্কর যুগ, লুণ্ঠন ব্যবস্থা, সভ্যতার বিচ্ছিন্নতা, অন্ধকার যুগ, নিয়মের বিশৃঙ্খলা</td></tr></tbody></table><h2 id="_1-প্রি-অ্যাঙ্কর-যুগের-মূল-বৈশিষ্ট্য" tabindex="-1">1. প্রি-অ্যাঙ্কর যুগের মূল বৈশিষ্ট্য <a class="header-anchor" href="#_1-প্রি-অ্যাঙ্কর-যুগের-মূল-বৈশিষ্ট্য" aria-label="Permalink to &quot;1. প্রি-অ্যাঙ্কর যুগের মূল বৈশিষ্ট্য&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগ হলো হেংইয়ান-ঝৌর ইতিহাসে সবচেয়ে দীর্ঘ এবং সবচেয়ে অন্ধকার যুগ। এই যুগে, মহাবিশ্বে কোনো একীভূত অ্যাঙ্কর প্রক্রিয়া বিদ্যমান ছিল না, মূল নিয়মগুলি প্রাকৃতিকভাবে ছড়িয়ে ছিটিয়ে থাকত, এবং শক্তি ও সম্পদের বিতরণ সম্পূর্ণরূপে &quot;শক্তিশালী ব্যক্তি এটি পায়&quot; জঙ্গলের নিয়ম অনুসরণ করত। লুণ্ঠনমূলক সাধনা ব্যবস্থা ছিল এই যুগের পরম প্রভাবশালী, সাধনার উপায়গুলি কয়েকজন শক্তিশালী ব্যক্তি এবং সম্প্রদায় দ্বারা একচেটিয়াভাবে নিয়ন্ত্রিত হত, এবং নিম্নস্তরের সাধারণ জীবদের কাছে আনুষ্ঠানিক বিবর্তনের পথ প্রায় ছিল না।</p><p>প্রি-অ্যাঙ্কর যুগের মূল বৈশিষ্ট্যগুলি &quot;পাঁচটি নেই&quot; হিসেবে সংক্ষেপে বলা যায়:</p><ul><li><strong>অ্যাঙ্কর নেই</strong>: স্থিতিশীল নিয়ম অ্যাঙ্কর ছিল না, শক্তির প্রবাহ বিশৃঙ্খল ছিল, এবং তলের প্রাচীরগুলি ভঙ্গুর ছিল</li><li><strong>শৃঙ্খলা নেই</strong>: কোনো একীভূত সভ্যতা ব্যবস্থা ছিল না, তলগুলির মধ্যে যুদ্ধ অব্যাহত ছিল, এবং বংশগত বিলুপ্তি ঘন ঘন হত</li><li><strong>পথ নেই</strong>: আন্তঃ-তল যোগাযোগ এবং পরিবহন প্রযুক্তি ছিল না, এবং তলগুলি মূলত বিচ্ছিন্ন অবস্থায় ছিল</li><li><strong>নিশ্চয়তা নেই</strong>: শিক্ষা, স্বাস্থ্যসেবা, আবাসন ইত্যাদি পাবলিক নিশ্চয়তা ব্যবস্থা ছিল না, এবং জীবনের অস্তিত্ব সম্পূর্ণরূপে ব্যক্তিগত ক্ষমতার উপর নির্ভর করত</li><li><strong>আশা নেই</strong>: নিম্নস্তরের জীবের বিবর্তনের চ্যানেল সম্পূর্ণরূপে বন্ধ ছিল, এবং শ্রেণির স্থিরতা চরম সীমায় পৌঁছেছিল</li></ul><h2 id="_2-লুণ্ঠনমূলক-সাধনা-ব্যবস্থার-কার্যকারিতা" tabindex="-1">2. লুণ্ঠনমূলক সাধনা ব্যবস্থার কার্যকারিতা <a class="header-anchor" href="#_2-লুণ্ঠনমূলক-সাধনা-ব্যবস্থার-কার্যকারিতা" aria-label="Permalink to &quot;2. লুণ্ঠনমূলক সাধনা ব্যবস্থার কার্যকারিতা&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগের সাধনা ব্যবস্থা লুণ্ঠনকে মূল কার্যকারিতা হিসেবে গ্রহণ করত। এর মূল যুক্তি ছিল: মহাবিশ্বের মূল শক্তি সীমিত, এবং ব্যক্তির বিবর্তন অবশ্যই অন্যের শক্তি খরচ করে সাধিত হয়। শক্তিশালী ব্যক্তিরা দুর্বলদের শক্তি, ভাগ্য এমনকি মূলতা গ্রাস করে নিজের উন্নতি সাধন করত, আর দুর্বলরা শক্তিশালীদের &quot;সাধনা সম্পদ&quot; হয়ে পড়ত।</p><p>লুণ্ঠনমূলক ব্যবস্থার সাধারণ রূপগুলির মধ্যে রয়েছে:</p><table tabindex="0"><thead><tr><th>লুণ্ঠনের ধরন</th><th>কার্যপদ্ধতি</th><th>মহাবিশ্বের উপর ক্ষতি</th></tr></thead><tbody><tr><td>শক্তি লুণ্ঠন</td><td>অন্যান্য জীবের সাধনা শক্তি সরাসরি আহরণ করা</td><td>ব্যক্তির মৃত্যু বা সাধনা সম্পূর্ণ নষ্ট হয়ে যায়</td></tr><tr><td>ভাগ্য লুণ্ঠন</td><td>জাদু বা আচারের মাধ্যমে অন্যের ভাগ্য ও সুযোগ আত্মসাৎ করা</td><td>কার্য-কারণ ভারসাম্য নষ্ট হয়, তল-স্তরের বিপর্যয় সৃষ্টি হয়</td></tr><tr><td>মূলতা লুণ্ঠন</td><td>অন্যান্য জীবের মূল নিয়মের টুকরোগুলি গ্রাস করা</td><td>অপরিবর্তনীয় বিবর্তনের সম্ভাবনা ক্ষতিগ্রস্ত হয়</td></tr><tr><td>তল লুণ্ঠন</td><td>শক্তিশালী ব্যক্তি সম্পূর্ণ তল জয় করে, তলের জীবদের সাধনা সম্পদ হিসেবে ব্যবহার করে</td><td>সভ্যতার বিলুপ্তি এবং তলের মরুভূমি সৃষ্টি হয়</td></tr><tr><td>নিয়ম লুণ্ঠন</td><td>তলের মূল নিয়মের নিয়ন্ত্রণ জোর করে আত্মসাৎ করা</td><td>নিয়ম নেটওয়ার্ক নষ্ট হয়, স্থানীয় পতন সৃষ্টি হয়</td></tr></tbody></table><p>লুণ্ঠনমূলক ব্যবস্থা স্বল্পকালীন কয়েকজন চরম শক্তিশালী ব্যক্তি তৈরি করতে পারে, কিন্তু দীর্ঘমেয়াদে এটি মহাবিশ্বের বিবর্তনের সম্ভাবনাকে ক্রমাগত খরচ করে, যার ফলে মহাবিশ্বের সামগ্রিক এনট্রপি বৃদ্ধি ত্বরান্বিত হয় এবং সভ্যতার বিচ্ছিন্নতা ঘন ঘন হয়।</p><h2 id="_3-সভ্যতার-বিচ্ছিন্নতা-এবং-চক্রাকার-ধ্বংস" tabindex="-1">3. সভ্যতার বিচ্ছিন্নতা এবং চক্রাকার ধ্বংস <a class="header-anchor" href="#_3-সভ্যতার-বিচ্ছিন্নতা-এবং-চক্রাকার-ধ্বংস" aria-label="Permalink to &quot;3. সভ্যতার বিচ্ছিন্নতা এবং চক্রাকার ধ্বংস&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগের সবচেয়ে উল্লেখযোগ্য ঐতিহাসিক ঘটনা হলো &quot;সভ্যতার বিচ্ছিন্নতা&quot;। লুণ্ঠনমূলক ব্যবস্থার অন্তর্নিহিত দ্বন্দ্বের কারণে, প্রতিটি একসময় উজ্জ্বল সভ্যতা শেষ পর্যন্ত আত্ম-ধ্বংসের দিকে এগিয়ে যায়:</p><ol><li><strong>উত্থান কাল</strong>: একটি বংশ বা সম্প্রদায় লুণ্ঠনের মাধ্যমে দ্রুত উত্থিত হয়, শক্তিশালী সভ্যতা প্রতিষ্ঠা করে</li><li><strong>চরম কাল</strong>: সভ্যতা শক্তির শীর্ষে পৌঁছায়, অভ্যন্তরীণ বিদ্রোহ দমন করে, বাহ্যিকভাবে লুণ্ঠনের জন্য সম্প্রসারিত হয়</li><li><strong>আন্তঃসংঘাত কাল</strong>: সভ্যতার অভ্যন্তরে শক্তিশালী ব্যক্তিরা সীমিত সম্পদের জন্য আন্তঃসংঘাতে লিপ্ত হয়, ক্ষমতা ক্ষয়প্রাপ্ত হয়</li><li><strong>পতন কাল</strong>: আন্তঃসংঘাতের ফলে সভ্যতার ক্ষমতা মারাত্মকভাবে হ্রাস পায়, বাহ্যিক লুণ্ঠনকারীরা সুযোগ নিয়ে প্রবেশ করে, এবং সভ্যতা বিলুপ্ত হয়</li><li><strong>বিচ্ছিন্নতা কাল</strong>: সভ্যতার বিলুপ্তির পরে, এর জ্ঞান এবং প্রযুক্তি বেশিরভাগই হারিয়ে যায়, এবং পরবর্তী সভ্যতাকে শূন্য থেকে শুরু করতে হয়</li></ol><p>&quot;উত্থান—চরম—আন্তঃসংঘাত—পতন—বিচ্ছিন্নতা&quot; এর এই চক্রটি প্রি-অ্যাঙ্কর যুগে অসংখ্যবার পুনরাবৃত্তি হয়েছে। প্রতিটি চক্র প্রচুর পরিমাণে মহাবিশ্বের মূলতা খরচ করেছে, যার ফলে মহাবিশ্বের সামগ্রিক বিবর্তনের স্তর দীর্ঘকাল ধরে স্থির থেকেছে বা এমনকি পিছিয়ে গেছে।</p><h2 id="_4-প্রি-অ্যাঙ্কর-যুগের-শেষকালের-লক্ষণ" tabindex="-1">4. প্রি-অ্যাঙ্কর যুগের শেষকালের লক্ষণ <a class="header-anchor" href="#_4-প্রি-অ্যাঙ্কর-যুগের-শেষকালের-লক্ষণ" aria-label="Permalink to &quot;4. প্রি-অ্যাঙ্কর যুগের শেষকালের লক্ষণ&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগের শেষকালে, মহাবিশ্বে পরিবর্তনের পূর্বাভাস দেওয়া কয়েকটি লক্ষণ উপস্থিত হয়েছিল:</p><ul><li><strong>নিয়মের বিশৃঙ্খলা বৃদ্ধি</strong>: দীর্ঘমেয়াদী লুণ্ঠনের ফলে নিয়ম নেটওয়ার্ক মারাত্মকভাবে ক্ষতিগ্রস্ত হয়েছে, স্থানীয় পতনের ঘটনা ঘন ঘন হয়েছে, এবং তলের প্রাচীরগুলি পাতলা হয়েছে</li><li><strong>জীবনের সম্ভাবনা ক্ষয়</strong>: লুণ্ঠনযোগ্য মূল শক্তি ক্রমশ কমে যাচ্ছে, এবং শক্তিশালী ব্যক্তিদের মধ্যে সম্পদের দাবদাহ তীব্র হয়ে উঠছে</li><li><strong>লুণ্ঠন-বিরোধী চিন্তার অঙ্কুর</strong>: কিছু বুদ্ধিজীবী লুণ্ঠনমূলক ব্যবস্থার মূল ত্রুটি প্রতিফলন করতে শুরু করেছেন এবং সহজাত বিবর্তনের প্রাথমিক ধারণা তৈরি করেছেন</li><li><strong>বিভিন্ন তলের যোগাযোগ বৃদ্ধি</strong>: তলের প্রাচীরের পাতলা হওয়ার ফলে বিভিন্ন তলের মধ্যে যোগাযোগ বৃদ্ধি পেয়েছে, এবং আন্তঃ-তল চিন্তা বিনিময় সম্ভব হয়েছে</li><li><strong>প্রথম প্রজন্মের অ্যাঙ্কর প্রার্থী উপস্থিত</strong>: মহাবিশ্বের কিছু কোণে, নিয়ম নেটওয়ার্কের সাথে প্রাকৃতিকভাবে অনুরণন করতে সক্ষম বিশেষ জীব উপস্থিত হয়েছে, যারা ভবিষ্যতের প্রথম প্রজন্মের অ্যাঙ্কর জাগরণকারীদের অগ্রদূত</li></ul><p>এই লক্ষণগুলি ইঙ্গিত করে যে লুণ্ঠনমূলক ব্যবস্থা শেষ প্রান্তে পৌঁছেছে, এবং মহাবিশ্ব একটি সম্পূর্ণ নতুন সভ্যতার রূপের আহ্বান জানাচ্ছে।</p><h2 id="_5-প্রি-অ্যাঙ্কর-যুগের-ঐতিহাসিক-উত্তরাধিকার" tabindex="-1">5. প্রি-অ্যাঙ্কর যুগের ঐতিহাসিক উত্তরাধিকার <a class="header-anchor" href="#_5-প্রি-অ্যাঙ্কর-যুগের-ঐতিহাসিক-উত্তরাধিকার" aria-label="Permalink to &quot;5. প্রি-অ্যাঙ্কর যুগের ঐতিহাসিক উত্তরাধিকার&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগ যদিও অন্ধকার ছিল, তবুও এটি সম্পূর্ণ মূল্যহীন ছিল না। এটি পরবর্তী অ্যাঙ্কর সিম্বায়োসিস সভ্যতার জন্য গুরুত্বপূর্ণ ঐতিহাসিক উত্তরাধিকার রেখে গেছে:</p><ul><li><strong>শিক্ষার উত্তরাধিকার</strong>: লুণ্ঠনমূলক ব্যবস্থার বারবার ব্যর্থতা সিম্বায়োসিস সভ্যতার জন্য সবচেয়ে গভীর বিপরীত পাঠ প্রদান করেছে, যা প্রমাণ করে যে লুণ্ঠনের পথ চলা সম্ভব নয়</li><li><strong>জ্ঞানের উত্তরাধিকার</strong>: যদিও সভ্যতার বিচ্ছিন্নতায় প্রচুর জ্ঞান হারিয়ে গেছে, তবুও কিছু সাধনা উপায় এবং নিয়মের বোঝাপড়া বিভিন্ন উপায়ে বেঁচে আছে, যা তিনশট মূল সাধনা ব্যবস্থার উপাদানের উৎস হয়েছে</li><li><strong>জীবনের উত্তরাধিকার</strong>: দীর্ঘ অন্ধকার যুগে বেঁচে থাকা বিভিন্ন জীবের রূপগুলি ভবিষ্যতের সর্ব-জাতি সিম্বায়োসিসের বংশগত ভিত্তি গঠন করেছে</li><li><strong>চেতনার উত্তরাধিকার</strong>: নিম্নস্তরের জীবের ন্যায়বিচার এবং আশার প্রতি দীর্ঘস্থায়ী আকাঙ্ক্ষা হলো অ্যাঙ্কর জাগরণের সবচেয়ে মূল মানসিক শক্তি</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>প্রি-অ্যাঙ্কর যুগ হলো হেংইয়ান-ঝৌর ইতিহাসের &quot;অন্ধকারের পূর্বরাত্রি&quot;। এর দীর্ঘতা এবং অন্ধকার, ঠিক উল্টোভাবে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার জন্মের মূল্য এবং অপরিহার্যতাকে প্রকাশ করে। প্রি-অ্যাঙ্কর যুগ বোঝা মানে সিম্বায়োসিস সভ্যতার &quot;লুণ্ঠনের বিরোধিতা, সিম্বায়োসিসের পক্ষে&quot; এই মূল অবস্থানের ঐতিহাসিক শিকড় বোঝা — এটি কোনো বিমূর্ত নৈতিক উপদেশ নয়, বরং অসংখ্য সভ্যতার ধ্বংসের বিনিময়ে অর্জিত রক্ত-আঁশুয়ে শিক্ষা।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>70-যুগ বিভাজন সারি সারণি</li><li>72-অ্যাঙ্কর জাগরণ যুগ</li><li>04-লুণ্ঠন-বিরোধীবাদ মূল প্রস্তাবনা</li></ul>',26)])])}const p=r(d,[["render",i]]);export{_ as __pageData,p as default};
